/*
 * The bearer token every server-function RPC carries.
 *
 * This carried the header "This file is automatically generated. Do not edit
 * it directly." Nothing generates it — no script in this repository writes it —
 * and `client.ts` already records the same finding about its own copy of that
 * header. Left in place it tells the next person their fix here will be
 * overwritten. It will not.
 */
import { createMiddleware } from "@tanstack/react-start";
import { loadSupabaseClient, loadSupabaseConfiguration } from "./on-demand";

/*
 * Must be registered as a global `functionMiddleware` in `src/start.ts`;
 * otherwise the browser never attaches the bearer token to serverFn RPCs.
 *
 * THAT REGISTRATION IS WHY THE CLIENT IS LOADED ON DEMAND HERE. `start.ts` is
 * the client entry, so anything it imports statically is in the entry bundle —
 * and a static import of the Supabase client put 200 KiB of auth, PostgREST,
 * realtime and storage in front of first paint for every visitor to the public
 * site, including pages that never call a server function at all.
 *
 * Nothing is deferred that matters: this callback is already async, and it runs
 * before an RPC — which only happens on screens that have loaded the client
 * anyway, where `import()` resolves from the module registry.
 */
export const attachSupabaseAuth = createMiddleware({ type: "function" }).client(
  async ({ next }) => {
    // Public and same-machine server functions do not require an account.
    // Avoid constructing the Supabase proxy when this local installation has
    // no account service; authenticated server functions still fail closed in
    // their own requireSupabaseAuth middleware.
    const configuration = await loadSupabaseConfiguration();
    if (!configuration.configured) {
      return next({ headers: {} });
    }
    const supabase = await loadSupabaseClient();
    const { data } = await supabase.auth.getSession();
    const token = data.session?.access_token;
    try {
      return await next({
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      });
    } catch (error) {
      /*
       * The server would not accept this token. If the auth server itself says
       * the same (the session was ended here, elsewhere, or by an operator),
       * this tab stops too, at once, instead of answering every click with a
       * failure until the token expires. The auth server is asked first: a
       * server that merely could not verify a token this once, or a network
       * blip, signs nobody out.
       */
      if (token && error instanceof Error && error.message.includes("Unauthorized:")) {
        void supabase.auth.getUser().then(async ({ error: refused }) => {
          if (!refused) return;
          const { mayUseCachedSession } = await import("@/lib/auth/session-failure");
          if (!mayUseCachedSession(refused)) await supabase.auth.signOut({ scope: "local" });
        });
      }
      throw error;
    }
  },
);
